1	use std::process::ExitCode;
2	
3	use callisto_graph::apply::{apply_version_plan, ApplyOptions, ApplyOutcome};
4	use callisto_graph::commands::VersionOptions;
5	use callisto_model::{ApplyPermit, DiagnosticSeverity};
6	
7	use crate::cli::{GlobalArgs, OutputFormat, VersionArgs};
8	use crate::error::CliError;
9	use crate::output::write_json;
10	use crate::render;
11	use crate::runner::CliCommandRunner;
12	use crate::workspace::{load_workspace, select_inference};
