14	pub fn handle(args: VersionArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
15	    if global.dry_run && args.emit_decision.is_some() {
16	        return Err(CliError::Other(
17	            "--emit-decision writes a file; remove --dry-run or drop --emit-decision".to_string(),
18	        ));
19	    }
20	
21	    let runner = CliCommandRunner;
22	    let ws = load_workspace(global, &runner)?;
23	
24	    let inference = select_inference();
25	    let opts = VersionOptions {
26	        strict: args.strict,
27	        strict_graph: args.strict_graph,
28	        allow_empty_changesets: args.allow_empty_changesets,
29	    };
30	
31	    let plan = callisto_graph::commands::plan_version(&ws, &inference, &opts)?;
32	
33	    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run);
34	
35	    if let (Some(path), Some(permit)) = (args.emit_decision.as_deref(), permit.as_ref()) {
36	        let decision = callisto_graph::commands::derive_release_decision(&ws, &plan)?;
37	        let content = serde_json::to_string_pretty(&decision).expect("release decision serializes") + "\n";
38	        // Relative to the workspace root, not the process's actual working
39	        // directory: this file must land inside the tree `--cwd` points at so
40	        // `git add -A` picks it up alongside the manifest and changelog
